async def act(page):
    """
    Search the site for the keyword 'Collector' using the site-aware helper when possible,
    then click the first search result. Robust accessibility-centric fallbacks are provided.

    Notes:
    - The knowledge-base helper create_curated_collection_by_search(...) is attempted first
      because it is specifically designed to drive the site's visible search widget.
    - All locator indexing is guarded by await locator.count() before .nth() to avoid
      indexing errors.
    - Any click or navigation expected to leave the page is the last action performed.
    """

    kb_results = None

    # 1) Try to use the knowledge-base helper to drive the visible search UI.
    #    This helper itself navigates to '/' and attempts to use the complementary region.
    try:
        kb_results = await create_curated_collection_by_search(page, "Collector", max_results=0, resolve_links=True)
    except Exception:
        kb_results = None

    # 2) Wait for the results area to render. Prefer role-based wait, fallback to networkidle.
    try:
        await page.get_by_role("main").wait_for(timeout=5000)
    except Exception:
        await page.wait_for_load_state("networkidle")

    # 3) Try to find article-based results and click the first link inside the first article.
    articles = page.get_by_role("article")
    try:
        article_count = await articles.count()
    except Exception:
        article_count = 0

    if article_count > 0:
        first_article = articles.nth(0)
        links_in_article = first_article.get_by_role("link")
        try:
            link_count = await links_in_article.count()
        except Exception:
            link_count = 0

        if link_count > 0:
            # Final action: click the first link inside the first article
            await links_in_article.nth(0).click()
            return
        else:
            # Fallback: click the article itself (best-effort navigation)
            try:
                await first_article.click()
            except Exception:
                pass
            return

    # 4) If no articles found in the current accessibility tree, perform a conventional
    #    relative search-results navigation and retry. This uses a relative goto as requested.
    try:
        await page.goto('/?s=Collector')
    except Exception:
        pass

    try:
        await page.get_by_role("main").wait_for(timeout=5000)
    except Exception:
        await page.wait_for_load_state("networkidle")

    # Retry article-based selection after fallback navigation.
    articles = page.get_by_role("article")
    try:
        article_count = await articles.count()
    except Exception:
        article_count = 0

    if article_count > 0:
        first_article = articles.nth(0)
        links_in_article = first_article.get_by_role("link")
        try:
            link_count = await links_in_article.count()
        except Exception:
            link_count = 0

        if link_count > 0:
            await links_in_article.nth(0).click()
            return
        else:
            try:
                await first_article.click()
            except Exception:
                pass
            return

    # 5) If still no article results, try clicking the first link inside <main>.
    main_links = page.get_by_role("main").get_by_role("link")
    try:
        main_link_count = await main_links.count()
    except Exception:
        main_link_count = 0

    if main_link_count > 0:
        await main_links.nth(0).click()
        return

    # 6) Final fallback: if the KB helper returned structured results with URLs,
    #    navigate to the first returned URL (substitute for clicking the visible result).
    if kb_results and isinstance(kb_results, (list, tuple)) and len(kb_results) > 0:
        first_item = kb_results[0]
        if isinstance(first_item, dict) and first_item.get("url"):
            await page.goto(first_item.get("url"))
            return

    # Nothing actionable found; do nothing.
    return

